INSERT INTO `areaclic` VALUES ('mdPerimetroToracico','Permetro Torcico','FITAMETRICA',NULL,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Per\\\'edmetro Tor\\\'e1cico (PT)\r\n\\par \\plain\\f3\\fs22 \r\n\\par Verificado com fita m\\\'e9trica flex\\\'edvel e inel\\\'e1stica. Passar a fita em torno do t\\\'f3rax, ao n\\\'edvel dos mamilos, sem comprimir as partes moles (tecidos) e se poss\\\'edvel, observando-se a leitura est\\\'e1 sendo feita durante a expira\\\'e7\\\'e3o ou inspira\\\'e7\\\'e3o. \r\n\\par \r\n\\par Fonte: JELLIFFE, D.B. \\endash  \\plain\\f3\\fs22\\ul Evaluaci\\\'f3n del estado de nutrici\\\'f3n de la comunidad.\\plain\\f3\\fs22  Ginebra, OMS, 1968. Figura 2.\r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',10);
